package com.example.discovery.consumer.service;import com.example.discovery.consumer.client.RegistryClient;import com.example.discovery.consumer.config.ConsumerProperties;import com.example.discovery.consumer.model.*;import java.util.*;import org.slf4j.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;@Service public class PaymentService{private static final Logger log=LoggerFactory.getLogger(PaymentService.class);private final RegistryClient registryClient;private final RoundRobinLoadBalancer lb;private final RestClient restClient;private final ConsumerProperties p;public PaymentService(RegistryClient registryClient,RoundRobinLoadBalancer lb,RestClient restClient,ConsumerProperties p){this.registryClient=registryClient;this.lb=lb;this.restClient=restClient;this.p=p;} public PaymentResponse getPayments(){List<ServiceInstance> instances=registryClient.discover();log.info("[CONSUMER] Discovered instances: {}",instances.stream().map(ServiceInstance::port).toList());for(ServiceInstance instance:lb.orderedCandidates(p.serviceName(),instances)){log.info("[CONSUMER] Selected instance: {}",instance.instanceId());try{return restClient.get().uri(instance.baseUrl()+"/payments").retrieve().body(PaymentResponse.class);}catch(Exception ex){log.warn("[CONSUMER] Instance {} unavailable",instance.instanceId());}}throw new ServiceUnavailableException("No available instances for "+p.serviceName());}}
